import Foundation

public enum ClipboardPolicy {
    public static let blockedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "com.agilebits.onepassword.private", "org.keepassxc.keepassxc",
        "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping", "Pasteboard generator type", "org.copysaver.owner",
        "public.file-url", "NSFilenamesPboardType", "public.png", "public.tiff",
    ]

    public static func allows(types: Set<String>, itemCount: Int) -> Bool {
        itemCount == 1 && types.contains("public.utf8-plain-text") && types.isDisjoint(with: blockedTypes)
    }

    public static func allows(text: String) -> Bool {
        guard text.utf8.count <= RecordLimits.maximumTextBytes,
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
        let upper = text.uppercased()
        if upper.contains("-----BEGIN ") && (upper.contains("PRIVATE KEY-----") || upper.contains("PGP PRIVATE KEY BLOCK-----")) { return false }
        // Narrow heuristic: ASCII digits with optional spaces/hyphens, 13–19 digits, Luhn checksum.
        let expression = try? NSRegularExpression(pattern: "(?<![0-9])[0-9](?:[ -]?[0-9]){12,18}(?![ -]?[0-9])")
        let range = NSRange(text.startIndex..., in: text)
        for match in expression?.matches(in: text, range: range) ?? [] {
            guard let range = Range(match.range, in: text) else { continue }
            let digits = text[range].utf8.filter { (48...57).contains($0) }.map { Int($0 - 48) }
            guard Set(digits).count > 1 else { continue }
            let sum = digits.reversed().enumerated().reduce(0) { total, pair in
                let n = pair.element * (pair.offset % 2 == 1 ? 2 : 1)
                return total + (n > 9 ? n - 9 : n)
            }
            if sum % 10 == 0 { return false }
        }
        return true
    }
}
